questionvariables.text:
/* Design: find the mistake in a square count, then give the right value. Entries [F, P, s, er]; er 1: part squares counted as whole; 2: part squares left out; 3: side used for the area of a square; 4: perimeter used. s = 4 is excluded (perimeter = area). Every shown answer is at least 10 m^2 from the correct one. Source: original. */
L: [[23,16,2,1],[31,18,5,2],[19,14,10,3],[27,20,3,4],[35,22,2,2],[24,18,5,1],[29,12,10,4],[21,26,3,3],[33,14,5,1],[26,24,2,2]];
ix: 1+rand(10);
F: L[ix][1]; P: L[ix][2]; s: L[ix][3]; er: L[ix][4];
est: F+P/2;
cor: est*s^2;
sh1: if er=1 then F+P elseif er=2 then F else F+P/2;
sh2: if er=3 then s elseif er=4 then 4*s else s^2;
sh3: sh1*sh2;
opts: [["e0",false,"Her working is correct."],["e1",is(er=1),"She counted each part square as a whole square."],["e2",is(er=2),"She left out the part squares."],["e3",is(er=3),"She used the length of a side of a square instead of its area."],["e4",is(er=4),"She used the perimeter of a square instead of its area."]];
kq: first(mcq_correct(opts));
/* test inputs: an option for the other step, and the other option for the same step */
wrongstep: if er >= 3 then "e1" else "e3";
samestep: if er=1 then "e2" elseif er=2 then "e1" elseif er=3 then "e4" else "e3";

feedbackvariables.text:
wstep: is((member(ans1,["e1","e2"]) and er >= 3) or (member(ans1,["e3","e4"]) and er <= 2));
ch: if ans1="e1" then 1 elseif ans1="e2" then 2 elseif ans1="e3" then 3 elseif ans1="e4" then 4 else 0;
wv: if ch=1 then F+P elseif ch=2 then F elseif ch=3 then s else 4*s;
